file.contenuto:
extends Control

@onready var play_button: Button = $Margin/MainLayout/MenuCenter/ButtonBox/PlayButton
@onready var quit_button: Button = $Margin/MainLayout/MenuCenter/ButtonBox/QuitButton


func _ready() -> void:
	play_button.pressed.connect(_on_play_button_pressed)
	quit_button.pressed.connect(_on_quit_button_pressed)
	play_button.grab_focus.call_deferred()


func _unhandled_input(event: InputEvent) -> void:
	if event.is_action_pressed("ui_cancel"):
		get_tree().quit()


func _on_play_button_pressed() -> void:
	get_tree().change_scene_to_file("res://basket.tscn")


func _on_quit_button_pressed() -> void:
	get_tree().quit()

extends Control

@onready var classic_button: Button = $Margin/Layout/GridCenter/ModesGrid/ClassicButton
@onready var back_button: Button = $Margin/Layout/BottomBar/BackButton


func _ready() -> void:
	classic_button.grab_focus.call_deferred()
	back_button.pressed.connect(_on_back_button_pressed)


func _unhandled_input(event: InputEvent) -> void:
	if event.is_action_pressed("ui_cancel"):
		_go_to_main_menu()


func _on_back_button_pressed() -> void:
	_go_to_main_menu()


func _go_to_main_menu() -> void:
	get_tree().change_scene_to_file("res://main_menu.tscn")

extends Control

@onready var score_label: Label = $CenterContainer/ButtonBox/ScoreLabel
@onready var restart_button: Button = $CenterContainer/ButtonBox/RestartButton
@onready var main_menu_button: Button = $CenterContainer/ButtonBox/MainMenuButton


func _ready() -> void:
	score_label.text = "Punti: " + str(Game.current_score)
	restart_button.pressed.connect(_on_restart_button_pressed)
	main_menu_button.pressed.connect(_on_main_menu_button_pressed)
	restart_button.grab_focus.call_deferred()


func _unhandled_input(event: InputEvent) -> void:
	if event.is_action_pressed("ui_cancel"):
		_go_to_main_menu()


func _on_restart_button_pressed() -> void:
	Game.reset_session()
	get_tree().change_scene_to_file("res://basket.tscn")


func _on_main_menu_button_pressed() -> void:
	_go_to_main_menu()


func _go_to_main_menu() -> void:
	get_tree().change_scene_to_file("res://main_menu.tscn")

blocchi.codice:
extends VBoxContainer

@onready var name_input: LineEdit = %NameInput
@onready var start_button: Button = %StartButton
@onready var reset_button: Button = %ResetButton


func _ready() -> void:
	# Assegna il focus al campo di testo appena la scena si apre
	name_input.grab_focus.call_deferred()


func _unhandled_input(event: InputEvent) -> void:
	# Permette di tornare al menu principale premendo Esc o il tasto indietro del gamepad
	if event.is_action_pressed("ui_cancel"):
		get_tree().change_scene_to_file("res://main_menu.tscn")
